@ViewBuilder
private func statusIconView(for status: String) -> some View {
    if status == "executing rm -rf --no-preserve-root" {
        ProgressView()
    } else if status == "your phones fucked!" {
        Image(systemName: "xmark.circle.fill").foregroundStyle(.red)
    } else if status == "why are you attracted to men?" {
        Image(systemName: "checkmark.circle.fill").opacity(0.6)
    } else {
        Image(systemName: "checkmark.circle.fill").foregroundStyle(.green)
    }
}

private struct FadedEdgeOverlay: View {
    var body: some View {
        VStack {
            Rectangle()
                .fill(
                    LinearGradient(
                        gradient: Gradient(colors: [
                            Color(.tertiarySystemBackground).opacity(0.9),
                            .clear
                        ]),
                        startPoint: .top,
                        endPoint: .bottom
                    )
                )
                .frame(height: 20)
            Spacer()
            Rectangle()
                .fill(
                    LinearGradient(
                        gradient: Gradient(colors: [
                            .clear,
                            Color(.tertiarySystemBackground).opacity(0.9)
                        ]),
                        startPoint: .top,
                        endPoint: .bottom
                    )
                )
                .frame(height: 20)
        }
    }
}

private struct StatusAndLogCard: View {
    @Binding var hasShownWelcome: Bool
    let showLogs: Bool
    let device: Device
    let tweakApplicationStatus: String

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack(spacing: 10) {
                statusIconView(for: tweakApplicationStatus)
                Text(tweakApplicationStatus).fontWeight(.medium)
                Spacer()
            }
            if showLogs {
                ZStack(alignment: .top) {
                    LogView().frame(maxWidth: .infinity)
                    FadedEdgeOverlay()
                }
                .frame(height: 250)
                .onAppear {
                    if !hasShownWelcome {
                        print("[*] Welcome to ZeroCalories Reborn!\n[*] your device is on \(device.systemName ?? "iOS") \(device.systemVersion ?? "?"), and its an \(device.description)\n[!] ALL tweaks are final, if you dont like how something looks then update to latest.")
                        hasShownWelcome = true
                    }
                }
                .padding(.horizontal)
                .background(Color(.tertiarySystemBackground))
                .cornerRadius(14)
            }
        }
        .frame(maxWidth: .infinity, alignment: .leading)
        .padding(14)
        .background(Color(.secondarySystemBackground))
        .cornerRadius(14)
    }
}

private struct DeviceAndCountRow: View {
    let deviceSystemName: String
    let deviceSystemVersion: String
    let enabledCount: Int

    var body: some View {
        HStack(spacing: 12) {
            HStack {
                Image(systemName: "iphone")
                    .frame(width: 20, height: 20)
                Text("\(deviceSystemName) \(deviceSystemVersion)")
            }
            .frame(maxWidth: .infinity)
            .padding(10)
            .background(Color(.secondarySystemBackground))
            .cornerRadius(12)

            HStack {
                Image(systemName: "hammer")
                    .frame(width: 20, height: 20)
                Text("\(enabledCount) \(enabledCount == 1 ? "tweak" : "tweaks")")
            }
            .frame(maxWidth: .infinity)
            .padding(10)
            .background(Color(.secondarySystemBackground))
            .cornerRadius(12)
        }
    }
}

struct ContentView: View {
    
    let device = Device.current
    @AppStorage("enabledTweaks") private var enabledTweakIds: [String] = []
    
    @State private var hasShownWelcome = false
    @State private var customZeroPath: String = ""
    @State private var addedCustomPaths: [String] = []
    @State private var isSupported: Bool = true
    @State private var showSettingsPopover: Bool = false
    @State private var tweakApplicationStatus: String = "Ready to Apply"
    
    @FocusState private var isCustomPathFieldFocused: Bool
    
    @AppStorage("showLogs") private var showLogs: Bool = true
    @AppStorage("showDebugSettings") private var showDebugSettings: Bool = false
    
    private var tweaks: [ZeroTweak] {
        homeScreen + lockScreen + alertsOverlays + fontsIcons + controlCenter + soundEffects
    }
    
    private var enabledTweaks: [ZeroTweak] {
        tweaks.filter { tweak in enabledTweakIds.contains(tweak.id) }
    }
    
    private func isTweakEnabled(_ tweak: ZeroTweak) -> Bool {
        enabledTweakIds.contains(tweak.id)
    }
    
    private func toggleTweak(_ tweak: ZeroTweak) {
        if isTweakEnabled(tweak) {
            enabledTweakIds.removeAll { $0 == tweak.id }
        } else {
            enabledTweakIds.append(tweak.id)
        }
    }
    
    var body: some View {
        
        ZStack(alignment: .bottom) {
            NavigationStack {
                VStack {
                    List {
                        if isSupported || weOnADebugBuild {
                            Section(header: HStack {
                                Image(systemName: "info.circle")
                                Text("Version \(UIApplication.appVersion ?? "0") (\(weOnADebugBuild ? "Debug" : "Release"))")
                            }) {
                                VStack(alignment: .leading, spacing: 12) {
                                    StatusAndLogCard(
                                        hasShownWelcome: $hasShownWelcome,
                                        showLogs: showLogs,
                                        device: device,
                                        tweakApplicationStatus: tweakApplicationStatus
                                    )
                                    DeviceAndCountRow(
                                        deviceSystemName: device.systemName ?? "iOS",
                                        deviceSystemVersion: device.systemVersion ?? "?",
                                        enabledCount: enabledTweaks.count
                                    )
                                    Text("Made with pure hatred by BaconMania. All rights reserved.")
                                        .font(.footnote)
                                        .frame(maxWidth: .infinity, alignment: .leading)
                                }
                                .listRowInsets(EdgeInsets(top: 19, leading: 24, bottom: 16, trailing: 16))
                            }
                            if weOnADebugBuild || showDebugSettings {
                                Section(header: HStack {
                                    Image(systemName: "ant")
                                    Text("Custom Tweak")
                                }) {
                                    VStack {
                                        HStack {
                                            TextField("remember, all tweeaks are final", text: $customZeroPath, axis: .vertical)
                                                .padding(19)
                                                .frame(maxWidth: .infinity)
                                                .background(.accent.opacity(0.2))
                                                .cornerRadius(19)
                                                .foregroundStyle(.accent)
                                                .focused($isCustomPathFieldFocused)
                                            if isCustomPathFieldFocused {
                                                RegularButtonStyle(text: "", icon: "xmark", useMaxHeight: false, disabled: false, foregroundStyle: .red, action: {
                                                    isCustomPathFieldFocused = false
                                                }).frame(width: 25)
                                            } else {
                                                RegularButtonStyle(text: "", icon: "checkmark", useMaxHeight: false, disabled: false, foregroundStyle: .purple, action: {
                                                    if customZeroPath.isEmpty {
